method twoSum(nums: array<int>, target: int) returns (i: int, j: int)
  requires nums != null
  requires nums.Length >= 2
  requires exists k1, k2 :: 0 <= k1 < k2 < nums.Length && nums[k1] + nums[k2] == target
  ensures 0 <= i < j < nums.Length
  ensures nums[i] + nums[j] == target
  ensures forall k1, k2 :: 0 <= k1 < k2 < i ==> nums[k1] + nums[k2] != target
{
  var n := nums.Length;
  i := 0;
  j := 1;
  while i < n - 1
    invariant 0 <= i < j <= n
    invariant forall ii, jj :: 0 <= ii < i && ii < jj < n ==> nums[ii] + nums[jj] != target
  {
    j := i + 1;
    while j < n
      invariant 0 <= i < j <= n
      invariant forall jj :: i < jj < j ==> nums[i] + nums[jj] != target
    {
      if nums[i] + nums[j] == target {
        return;
      }
      j := j + 1;
    }

    i := i + 1;
  }
}

