  ensures forall i :: 0 <= i < b.Length ==> b[i] == a[i]
  ensures forall j :: 0 <= j < c.Length ==> c[j] == a[a.Length / 2 + j]
  ensures a.Length == b.Length + c.Length
{
  var splitPoint : int := a.Length / 2;

  b := new int[splitPoint];
  c := new int[a.Length - splitPoint];

  var i : int := 0;

  while (i < splitPoint)
    invariant 0 <= i <= splitPoint
    invariant b[..i] == a[..i]
  {
    b[i] := a[i];
    i := i + 1;
  }

  // while(i < a.Length)
  //   invariant splitPoint <= i <= a.Length
  //   invariant c[..i-splitPoint] == a[..i]
  // {
  //   c[i] := a[i];
  //   i := i+1;
  // }

  var j : int := 0;
  while (i < a.Length)
    invariant splitPoint <= i <= a.Length
    invariant j == i - splitPoint
    invariant c[..j] == a[splitPoint..i]
    invariant b[..] + c[..j] == a[..i]
  {
    c[j] := a[i];
    i := i + 1;
    j := j + 1;
  }

}

method FindMax(a: array<int>) returns (i: int)
