    //     0    k   k+511  1000
    if a[k+255] < x { k := k+256; }
    // a: | <x | ??? | >= x|
    //     ^    ^     ^     ^
    //     0    k   k+255  1000
    if a[k+127] < x { k := k+128; }
    if a[k+63] < x  { k := k+64;  }
    if a[k+31] < x  { k := k+32;  }
