method Product(m: nat, n:nat) returns (res:nat)
ensures res == m*n;
{
    var m1: nat := m;
    res:=0;

    while (m1 != 0)   
    invariant 0 <= m1 <= m;
    decreases m1;
    invariant res == (m-m1)*n;
    {
        var n1: nat := n;
        while (n1 != 0) 
        invariant 0 <= n1 <= n;
        decreases n1;
