method Getmini(a:array<int>) returns(mini:nat) 
  requires a.Length > 0
  ensures mini < a.Length
  ensures 0 <= mini
  ensures forall j :: 0 <= j < a.Length ==> a[mini] <= a[j]
  ensures forall k :: 0 <= k < mini ==> a[k] > a[mini]
{
    // find mini
    var min:int := a[0];
    var i:int := 0;
    while i < a.Length
    invariant 0 <= i <= a.Length
    invariant forall x :: 0 <= x < i ==> min <= a[x] // min is the smallest so far
    invariant min in a[..] // min is always in a
    {
        if a[i] < min {
            min := a[i];
        }
        i := i + 1;
    }

    //assert min in a[..]; // min is in a -> it will be found by this loop
    // find first occurance
    var k:int := 0;
    while k < a.Length 
    invariant 0 <= k <= a.Length
    invariant forall x :: 0 <= x < k ==> min < a[x]
    {
        if a[k] == min {
            return k;
        }
        k := k + 1;
    }
}

