  ensures c == -1 || (0 <= c && c < a.Length && a[c] == 'e')
  ensures c == -1 ==> (forall i | 0 <= i < a.Length :: a[i] != 'e')
  ensures c != -1 ==> (forall i | 0 <= i < c :: a[i] != 'e')
{
    var i:int := 0;
    while i < a.Length
    invariant 0 <= i <= a.Length
    invariant forall x :: 0 <= x < i ==> a[x] != 'e'
