method LinearSearch(a: array<int>, key: int) returns (n: nat)
  ensures n <= a.Length
  ensures if exists i :: 0 <= i < a.Length && a[i] == key then n < a.Length && a[n] == key && (forall j :: 0 <= j < n ==> a[j] != key) else n == a.Length
{
  n := 0;
  while n < a.Length
    invariant n <= a.Length
  {
    if a[n] == key {
      return;
    }
    n := n + 1;
  }
}

