method SmallestMissingNumber(s: seq<int>) returns (v: int)
  ensures v >= 0
  ensures forall i :: 0 <= i < v ==> (i in s || exists k :: 0 <= k < |s| && s[k] == i)
  ensures !(v in s)
{
    v := 0;
    for i := 0 to |s|
        invariant 0 <= i <= |s|
        invariant 0 <= v <= i
        invariant v !in s[..i]
        invariant forall k :: 0 <= k < v && s[k] != v ==> k in s[..i]
    {
        if s[i] > v
        {
            break;
        }
        else
        {
            if s[i] == v 
            {
                v := v + 1;
            }
        }
    }
    assert forall k :: 0 <= k < v && s[k] != v ==> k in s;
}

