  ensures old(arr) == arr
  ensures if exists i :: 0 <= i < arr.Length && arr[i] == target then index == min i :: 0 <= i < arr.Length && arr[i] == target else index == -1
{
    index := -1;
    for i := 0 to arr.Length
        invariant 0 <= i <= arr.Length
        invariant index == -1 ==> forall k :: 0 <= k < i ==> arr[k] != target
        invariant 0 <= index < i ==> arr[index] == target
        invariant forall k :: 0 <= k < arr.Length ==> arr[k] == old(arr[k])
    {
        if arr[i] == target
        {
            index := i;
            break;
        }
        if arr[i] > target
        {
            break;
        }
    }
}

method RotateRight(l: seq<int>, n: int) returns (r: seq<int>)
  ensures |r| == |l|
  ensures forall k :: 0 <= k < |l| ==> r[k] == l[(k - n + |l|) % |l|]
{
    var rotated: seq<int> := [];
    for i := 0 to |l|
        invariant 0 <= i <= |l|
        invariant |rotated| == i
        invariant forall k :: 0 <= k < i ==> rotated[k] == l[(k - n + |l|) % |l|]
    {
        rotated := rotated + [l[(i - n + |l|) % |l|]];
    }
    return rotated;
}

