method Difference(a: seq<int>, b: seq<int>) returns (diff: seq<int>)
  ensures forall i :: 0 <= i < |diff| ==> diff[i] in a
  ensures forall i :: 0 <= i < |diff| ==> !(diff[i] in b)
  ensures forall i, j :: 0 <= i < j < |diff| ==> diff[i] != diff[j]
  ensures forall x :: x in a && !(x in b) ==> x in diff
  ensures forall i :: 0 <= i < |diff| ==> exists j :: 0 <= j < |a| && a[j] == diff[i] && (forall k :: 0 <= k < j ==> a[k] != diff[i])
{
    diff := [];
    for i := 0 to |a|
        invariant 0 <= i <= |a|
        invariant forall x :: x in diff <==> (x in a[..i] && x !in b)
        invariant forall i, j :: 0 <= i < j < |diff| ==> diff[i] != diff[j]
    {
        if a[i] !in b && a[i] !in diff
        {
            diff := diff + [a[i]];
        }
    }
}

method SumOfFourthPowerOfOddNumbers(n: int) returns (sum: int)
  requires n >= 0
  ensures sum == n * (2*n + 1) * (24*n*n*n - 12*n*n - 14*n + 7) / 15
{
    sum := 0;
    var i := 1;
    for k := 0 to n
        invariant 0 <= k <= n
        invariant i == 2 * k + 1
        invariant sum == k * (2 * k + 1) * (24 * k * k * k - 12 * k * k  - 14 * k + 7) / 15
    {
        sum := sum + i * i * i * i;
        i := i + 2;
    }
}

